  // Use a trick: find the UTC equivalent of 6:30 PM in each zone
  // by iterating
  const target = new Date('2025-11-27T18:30:00Z');
  const utcStr = target.toLocaleString('en-US', { timeZone: zones[i], hour12: false });

  // Better approach: use the timezone offset
  const jan = new Date('2025-11-27T18:30:00');
