// Cleaner approach
const moment = (tz) => {
  // Create date parts for 2025-11-27 18:30:00 in the given timezone
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, year: 'numeric', month: 'numeric', day: 'numeric',
    hour: 'numeric', minute: 'numeric', second: 'numeric', hour12: false
  });

  // We need the reverse: given a local time in tz, find the UTC timestamp
  // Trick: start with a guess, then adjust
  let guess = new Date('2025-11-27T18:30:00Z');
  const parts = formatter.formatToParts(guess);
  const get = (type) => parseInt(parts.find(p => p.type === type).value);
  const localInTz = new Date(get('year'), get('month')-1, get('day'), get('hour') === 24 ? 0 : get('hour'), get('minute'), get('second'));
  const target = new Date(2025, 10, 27, 18, 30, 0);
  const diff = target - localInTz;
  const result = new Date(guess.getTime() + diff);
  return Math.floor(result.getTime() / 1000);
};

for (let i = 0; i < zones.length; i++) {
  const ts = moment(zones[i]);
  console.log(labels[i].padEnd(16) + ': ' + ts);
}
